import java.util.concurrent.*

class Foo {
    private val asyncPool = Executors.newFixedThreadPool(10)

    fun bad(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync { isBlocked(it) } // bad, uses common pool
        }
    }

    fun good(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync({ isBlocked(it) }, asyncPool) // good
        }
    }
}
